494: function syncIntel(h) {
495:   const activeMap = game.started ? game.map : selectedMap;
496:   const key = `${activeMap.id}:${game.started}:${h.wave}:${h.phase}`;
497:   if (key === lastIntelKey) return;
498:   lastIntelKey = key;
499:   const body = $('#intelBody');
500:   const threat = $('#intelThreat');
501:   const title = $('#intelTitle');
502:   if (!body) return;
503:   if (!game.started) {
504:     body.innerHTML = '<span class="intel-tip">Deploy the outpost to see enemy movements.</span>';
505:     threat.textContent = 'STANDBY';
506:     threat.className = 'threat';
507:     return;
508:   }
509:   if (h.phase === 'victory' || h.phase === 'defeat') {
510:     body.innerHTML = '<span class="intel-tip">Mission concluded. Redeploy for another run.</span>';
511:     threat.textContent = h.phase === 'victory' ? 'SECURED' : 'OFFLINE';
512:     threat.className = 'threat';
513:     return;
514:   }
515:   title.textContent = h.phase === 'wave' ? 'WAVE INTEL' : 'NEXT WAVE INTEL';
516:   const specs = makeWave(h.wave, activeMap.id);
517:   const counts = {};
518:   for (const s of specs) counts[s.type] = (counts[s.type] || 0) + 1;
519:   const roster = activeMap.roster;
520:   const order = [...new Set([roster.line, roster.fast, roster.heavy, roster.boss])];
521:   body.innerHTML = order
522:     .filter(t => counts[t])
523:     .map((t) => {
524:       const def = ENEMY_TYPES[t];
525:       return `<span class="intel-chip"><i class="enemy-dot ${def.boss ? 'boss' : ''}" style="--dotc:${def.color}"></i><b>${counts[t]}</b>${def.short}</span>`;
526:     })
527:     .join('');
528:   let level = 'LOW';
529:   const bossEvery = activeMap.bossEvery ?? 10;
530:   const bossWave = (bossEvery > 0 && h.wave % bossEvery === 0) || h.wave === activeMap.waves;
531:   if (h.wave > 18 || bossWave) level = 'EXTREME';
532:   else if (h.wave > 11) level = 'HIGH';
533:   else if (h.wave > 4) level = 'MODERATE';
534:   threat.textContent = `${level} THREAT`;
535:   threat.className = `threat ${level === 'MODERATE' ? 'moderate' : level === 'HIGH' ? 'high' : level === 'EXTREME' ? 'extreme' : ''}`;
536: }
