900:     if (game.pendingType) { cancelPlacement(); return; }
901:     if (game.selected) { closeInspector(); return; }
902:     return;
903:   }
904:   if (!game.started) {
905:     if (e.key === 'Enter' || e.key === ' ') {
906:       e.preventDefault();
907:       if (!startScreen.classList.contains('hidden')) {
908:         audio.ensure(); audio.ui(); showMenuScreen('home');
909:       } else if (!homeScreen.classList.contains('hidden')) {
910:         audio.ui(); showMenuScreen('map');
