918:   }
919:   if (e.key === 'p' || e.key === 'P') { setPaused(!game.paused); return; }
920:   if (e.key === 'm' || e.key === 'M') {
921:     audio.ensure(); audio.setMuted(!audio.muted); syncUI(true); return;
922:   }
923:   const idx = Number(e.key);
924:   if (idx >= 1 && idx <= TOWER_ORDER.length) {
925:     const type = TOWER_ORDER[idx - 1];
926:     if (game.credits < TOWERS[type].cost) {
927:       audio.error();
