169: export function mulberry32(a) {
170:   return function () {
171:     a |= 0;
172:     a = (a + 0x6d2b79f5) | 0;
173:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
174:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
175:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
176:   };
