179: function roundRect(ctx, x, y, w, h, r) {
180:   const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
181:   ctx.beginPath();
182:   ctx.moveTo(x + rr, y);
183:   ctx.arcTo(x + w, y, x + w, y + h, rr);
184:   ctx.arcTo(x + w, y + h, x, y + h, rr);
185:   ctx.arcTo(x, y + h, x, y, rr);
186:   ctx.arcTo(x, y, x + w, y, rr);
187:   ctx.closePath();
188: }
