190: function tracePoints(ctx, pts) {
191:   if (!pts.length) return;
192:   ctx.beginPath();
193:   ctx.moveTo(pts[0][0], pts[0][1]);
194:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
