197: function offsetPath(pts, off) {
198:   const out = [];
199:   for (let i = 0; i < pts.length; i++) {
200:     const p = pts[i];
201:     const prev = pts[Math.max(0, i - 1)];
202:     const next = pts[Math.min(pts.length - 1, i + 1)];
203:     let dx = next[0] - prev[0];
204:     let dy = next[1] - prev[1];
205:     const l = Math.hypot(dx, dy) || 1;
206:     dx /= l; dy /= l;
207:     out.push([p[0] - dy * off, p[1] + dx * off]);
208:   }
209:   return out;
210: }
