44: function pointDistanceToPath(x, y, pts) {
45:   let best = Infinity;
46:   for (let i = 0; i < pts.length - 1; i++) {
47:     const ax = pts[i][0], ay = pts[i][1];
48:     const bx = pts[i + 1][0], by = pts[i + 1][1];
49:     const dx = bx - ax, dy = by - ay;
50:     const l2 = dx * dx + dy * dy || 1;
51:     let t = ((x - ax) * dx + (y - ay) * dy) / l2;
52:     t = clamp(t, 0, 1);
