597:       if (e.slowT > 0) {
598:         e.slowT -= dt;
599:         if (e.slowT <= 0) { e.slowT = 0; e.slowFactor = 0; }
600:       }
601:       const slowMul = e.slowT > 0 ? 1 - e.slowFactor : 1;
602:       const pxPerSec = e.speed * this.S * slowMul;
603:       e.t += (pxPerSec * dt) / this.pathLen;
604:       if (e.t >= 1) {
