662:       if (t.mode === 'first') score = e.t;
663:       else if (t.mode === 'last') score = -e.t;
664:       else if (t.mode === 'strong') score = e.hp;
665:       else score = -d2;
666:       if (score > bestScore) { bestScore = score; best = e; }
667:     }
668:     return best;
669:   }
