840:   ionBurst(x, y, radius, source) {
841:     if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(radius) || radius <= 0) return;
842:     const segments = 7;
843:     for (const other of this.enemies) {
844:       if (other.dead) continue;
845:       if (Math.hypot(other.x - x, other.y - y) < radius + other.radius * this.S) {
846:         this.slowEnemy(other, 0.55, 1.4);
847:         this.spark(other.x, other.y, 3, '#8cecff', 2);
848:       }
849:     }
850:     if (source) {
851:       const pts = [];
852:       for (let i = 0; i <= segments; i++) {
853:         const t = i / segments;
854:         const px = source.x + (x - source.x) * t;
855:         const py = source.y + (y - source.y) * t;
856:         const jitter = i === 0 || i === segments ? 0 : (Math.random() - 0.5) * 22 * this.S;
857:         pts.push([px + jitter, py + jitter * 0.6]);
858:       }
859:       this.effects.push({ kind: 'arc', points: pts, color: '#7fe6ff', width: 1.7 * this.S, life: 0.2, max: 0.2 });
860:     }
861:     this.effects.push({ kind: 'ring', x, y, r: 4, maxR: radius, color: '#8deaff', width: 2, life: 0.35, max: 0.35 });
862:     this.effects.push({ kind: 'flash', x, y, r: radius * 0.8, color: 'rgba(120, 230, 255, 0.4)', life: 0.2, max: 0.2 });
863:   }
