872:   updateProjectiles(dt) {
873:     for (const p of this.projectiles) {
874:       if (p.dead) continue;
875:       p.life -= dt;
876:       if (p.life <= 0) { p.dead = true; continue; }
877:       if (p.kind === 'ion') p.spin += dt * 9;
878:       const target = p.target;
879:       if (target && !target.dead) {
880:         const dx = target.x - p.x;
881:         const dy = target.y - p.y;
882:         const d = Math.hypot(dx, dy);
883:         p.angle = Math.atan2(dy, dx);
884:         const step = p.speed * dt;
885:         if (d <= step + target.radius * this.S * 0.8 + 4) {
886:           this.projectileHit(p, target);
887:           p.dead = true;
888:           continue;
889:         }
890:         p.x += (dx / d) * step;
891:         p.y += (dy / d) * step;
892:         if (p.kind === 'rocket') {
893:           const life = 0.3 + Math.random() * 0.25;
894:           this.particles.push({
895:             x: p.x - Math.cos(p.angle) * 7 * this.S,
896:             y: p.y - Math.sin(p.angle) * 7 * this.S,
897:             vx: (Math.random() - 0.5) * 12 * this.S,
898:             vy: (Math.random() - 0.5) * 12 * this.S - 4 * this.S,
899:             life, max: life, size: (2 + Math.random() * 2.2) * this.S,
900:             color: 'rgba(150, 142, 128, 0.4)', glow: false, gravity: -6, drag: 0.98,
901:           });
902:         }
903:       } else {
904:         const step = p.speed * dt;
905:         p.x += Math.cos(p.angle) * step;
906:         p.y += Math.sin(p.angle) * step;
907:         if (p.splash && target) {
908:           // payload falls short but still detonates
909:           this.projectileHit(p, null);
910:           p.dead = true;
911:         }
912:       }
913:     }
914:     this.projectiles = this.projectiles.filter(p => !p.dead);
915:   }
916: 
917:   projectileHit(p, target) {
918:     if (p.kind === 'bullet') {
919:       if (target) {
920:         this.damageEnemy(target, p.damage);
921:         this.spark(target.x, target.y, 3, '#ffd480', 2);
922:       }
923:     } else if (p.kind === 'rocket') {
924:       const R = p.splash;
925:       for (const e of this.enemies) {
926:         if (e.dead) continue;
927:         const d = Math.hypot(e.x - p.x, e.y - p.y);
928:         if (d < R + e.radius * this.S) {
929:           const falloff = 1 - clamp((d - e.radius * this.S) / R, 0, 1) * 0.45;
930:           this.damageEnemy(e, p.damage * falloff);
931:         }
932:       }
933:       this.explosion(p.x, p.y, R, false);
934:       this.shake = Math.max(this.shake, 1.8);
935:     } else if (p.kind === 'ion') {
936:       if (target) this.damageEnemy(target, p.damage);
